// Helper function to get all assets by license
window.getCitPackAssetsByLicense = function(license) {
  const all = [
    ...window.CITY_PACK_ASSETS.buildings,
    ...window.CITY_PACK_ASSETS.vehicles,
    ...window.CITY_PACK_ASSETS.props,
    ...window.CITY_PACK_ASSETS.vegetation,
    ...window.CITY_PACK_ASSETS.characters
  ];
  return all.filter(a => a.license === license);
}

// Helper function to get random asset from category
window.getRandomCityPackAsset = function(category) {
  const assets = window.CITY_PACK_ASSETS[category];
  if (!assets || assets.length === 0) return null;
  return assets[Math.floor(Math.random() * assets.length)];
}
